===BEGIN llm_candidates.jsonl===
{"title":"Opening Up Closings","url":"https://doi.org/10.1515/semi.1973.8.4.289","doi":"10.1515/semi.1973.8.4.289","authors":["Emanuel A. Schegloff","Harvey Sacks"],"year":1973,"venue":"Semiotica","abstract":"Analyzes how conversational participants collaboratively bring interactions to a close, developing an account based on sequential organization, turn structure, topic organization, and the conditional relevance of conversational actions."}
{"title":"A Simplest Systematics for the Organization of Turn-Taking for Conversation","url":"https://doi.org/10.2307/412243","doi":"10.2307/412243","authors":["Harvey Sacks","Emanuel A. Schegloff","Gail Jefferson"],"year":1974,"venue":"Language","abstract":"Presents a locally managed and interactionally controlled model of conversational turn taking, providing foundational machinery for understanding how responses are sequentially related to preceding conversational actions."}
{"title":"Questions in Montague English","url":"https://www.jstor.org/stable/25000703","authors":["Charles L. Hamblin"],"year":1973,"venue":"Foundations of Language","abstract":"Develops a formal semantic treatment of questions in which questions are associated with sets of possible answers, providing an influential foundation for later work on answerhood and question resolution."}
{"title":"Syntax and semantics of questions","url":"https://link.springer.com/article/10.1007/BF00351935","doi":"10.1007/BF00351935","authors":["Lauri Karttunen"],"year":1977,"venue":"Linguistics and Philosophy","abstract":"Provides a compositional semantic analysis of questions and their possible answers, establishing machinery that later work uses to characterize when propositions answer or partially resolve a question."}
{"title":"Studies on the Semantics of Questions and the Pragmatics of Answers","url":"https://hdl.handle.net/11245/1.392528","authors":["Jeroen Groenendijk","Martin Stokhof"],"year":1984,"venue":"University of Amsterdam doctoral dissertation","abstract":"Develops a systematic formal account of question semantics and the pragmatics of answers, including how propositions partition possibilities and contribute to resolving information requested by a question."}
{"title":"Resolving questions, I","url":"https://link.springer.com/article/10.1007/BF00985365","authors":["Jonathan Ginzburg"],"year":1995,"venue":"Linguistics and Philosophy","abstract":"Develops a formal account of how questions are resolved in discourse, connecting question meaning, contextual information, and the semantic contribution of responses."}
{"title":"Resolving questions, II","url":"https://link.springer.com/article/10.1007/BF00983299","doi":"10.1007/BF00983299","authors":["Jonathan Ginzburg"],"year":1995,"venue":"Linguistics and Philosophy","abstract":"Extends the formal theory of question resolution to additional discourse phenomena and clarifies how conversational context constrains what counts as an appropriate resolution of a question."}
{"title":"Questions in Dialogue","url":"https://www.research.ed.ac.uk/en/publications/questions-in-dialogue/","doi":"10.1023/A:1005364332007","authors":["Nicholas Asher","Alex Lascarides"],"year":1998,"venue":"Linguistics and Philosophy","abstract":"Integrates question semantics with discourse structure and dialogue interpretation, examining how discourse relations and participants' information states constrain the interpretation of questions and answers."}
{"title":"Information Structure: Towards an integrated formal theory of pragmatics","url":"https://semprag.org/article/view/sp.5.6","doi":"10.3765/sp.5.6","authors":["Craige Roberts"],"year":2012,"published":"2012-12-19","venue":"Semantics and Pragmatics","abstract":"Develops a Questions Under Discussion account of discourse organization in which questions structure conversational goals and propositions are relevant insofar as they address the current question under discussion."}
{"title":"Discourse Deixis: Reference to Discourse Segments","url":"https://aclanthology.org/P88-1014/","doi":"10.3115/982023.982037","authors":["Bonnie Lynn Webber"],"year":1988,"venue":"26th Annual Meeting of the Association for Computational Linguistics","abstract":"Presents a computational account of discourse-deictic expressions whose referents are interpretations associated with portions of prior discourse rather than ordinary nominal entities."}
{"title":"Structure and ostension in the interpretation of discourse deixis","url":"https://www.research.ed.ac.uk/en/publications/structure-and-ostension-in-the-interpretation-of-discourse-deixis/","doi":"10.1080/01690969108406940","authors":["Bonnie Lynn Webber"],"year":1991,"venue":"Language and Cognitive Processes","abstract":"Examines demonstrative expressions that refer to interpretations of one or more clauses and argues that discourse structure constrains which prior discourse segments are available for deictic reference."}
{"title":"Reference to Abstract Objects in Discourse","url":"https://link.springer.com/book/10.1007/978-94-011-1715-9","doi":"10.1007/978-94-011-1715-9","authors":["Nicholas Asher"],"year":1993,"venue":"Studies in Linguistics and Philosophy","abstract":"Develops a semantic theory of reference to abstract entities such as propositions, facts, events, and situations, providing a foundational treatment of how discourse introduces and subsequently refers to such objects."}
{"title":"Dialogue Acts, Synchronizing Units, and Anaphora Resolution","url":"https://academic.oup.com/jos/article-abstract/17/1/51/1613717","doi":"10.1093/jos/17.1.51","authors":["Miriam Eckert","Michael Strube"],"year":2000,"published":"2000-02-01","venue":"Journal of Semantics","abstract":"Studies anaphora in spontaneous dialogue and proposes an account linking dialogue structure and synchronizing units to the interpretation of anaphoric expressions, including references whose antecedents are not simple nominal entities."}
{"title":"Resolving Pronominal Reference to Abstract Entities","url":"https://doi.org/10.3115/1073083.1073099","doi":"10.3115/1073083.1073099","authors":["Donna K. Byron"],"year":2002,"venue":"Proceedings of the 40th Annual Meeting of the Association for Computational Linguistics","abstract":"Introduces a computational approach for resolving pronouns that refer to abstract entities as well as ordinary individuals, explicitly constructing candidate abstract referents from preceding discourse."}
{"title":"Annotating Abstract Pronominal Anaphora in the DAD Project","url":"https://aclanthology.org/L08-1331/","authors":["Costanza Navarretta","Sussi Olsen"],"year":2008,"venue":"LREC 2008","abstract":"Describes annotation of abstract pronominal anaphora in Danish and Italian data, covering antecedents realized by verb phrases, clauses, and larger discourse segments and referents such as events, situations, and propositions."}
{"title":"Annotating Discourse Anaphora","url":"https://aclanthology.org/W09-3031/","authors":["Stefanie Dipper","Heike Zinsmeister"],"year":2009,"abstract":"Develops corpus annotation guidelines for discourse-deictic anaphora, including identification of antecedent material and semantic referent types, using German discourse data with speaker turns."}
{"title":"Antecedent and Referent Types of Abstract Pronominal Anaphora","url":"https://www.researchgate.net/publication/236649715_Antecedent_and_Referent_Types_of_Abstract_Pronominal_Anaphora","authors":["Costanza Navarretta"],"year":2011,"venue":"Beyond Semantics: Corpus-based Investigations of Pragmatic and Discourse Phenomena","abstract":"Analyzes abstract pronominal anaphora with respect to syntactic antecedent types, semantic referent types, and antecedent distance, including clauses and discourse segments referring to events, situations, properties, and propositions."}
{"title":"The Use of Parallel and Comparable Data for Analysis of Abstract Anaphora in German and English","url":"https://aclanthology.org/L12-1038/","authors":["Stefanie Dipper","Melanie Seiss","Heike Zinsmeister"],"year":2012,"venue":"LREC 2012","abstract":"Uses parallel and comparable English-German data to study features useful for abstract-anaphora analysis and resolution, with attention to discourse-deictic antecedents and cross-linguistic evidence."}
{"title":"Resolving Shell Nouns","url":"https://aclanthology.org/D14-1056/","doi":"10.3115/v1/D14-1056","authors":["Varada Kolhatkar","Graeme Hirst"],"year":2014,"venue":"EMNLP 2014","abstract":"Addresses automatic resolution of shell nouns to the clauses or other textual material that supply their semantic content, treating the problem as locating potentially non-nominal antecedent spans."}
{"title":"A Mention-Ranking Model for Abstract Anaphora Resolution","url":"https://arxiv.org/abs/1706.02256","arxiv_id":"1706.02256","doi":"10.18653/v1/D17-1021","authors":["Ana Marasović","Leo Born","Juri Opitz","Anette Frank"],"year":2017,"venue":"EMNLP 2017","abstract":"Formulates abstract-anaphora resolution as mention ranking and learns to score candidate antecedent spans for abstract anaphors, combining neural representation learning with training data derived from shell-noun constructions."}
{"title":"Detecting and Resolving Shell Nouns in German","url":"https://aclanthology.org/W18-0707/","doi":"10.18653/v1/W18-0707","authors":["Adam Roussel"],"year":2018,"venue":"CRAC 2018","abstract":"Presents a system that first detects shell-noun constructions and then links shell nouns to textual content phrases, including explicit modeling of candidates for which no valid content link should be made."}
{"title":"Anaphora With Non-nominal Antecedents in Computational Linguistics: a Survey","url":"https://aclanthology.org/J18-3007/","doi":"10.1162/coli_a_00327","authors":["Varada Kolhatkar","Adam Roussel","Stefanie Dipper","Heike Zinsmeister"],"year":2018,"venue":"Computational Linguistics","abstract":"Surveys computational research on anaphors whose antecedents are clauses, sentences, or discourse segments and whose referents may be propositions, events, facts, or situations, covering terminology, annotation, datasets, and resolution methods."}
{"title":"Resolving abstract anaphors in Spanish discourse: Underspecification and mereological structures","url":"https://scholarworks.indianapolis.iu.edu/items/565d6b77-ed93-4303-a752-1daaf06bbd37","authors":["Iker Zulaica-Hernández"],"year":2018,"abstract":"Examines abstract anaphora in Spanish where several preceding propositions or eventualities may contribute to the interpretation, using discourse structure and mereological relations to represent complex abstract referents."}
{"title":"The CODI-CRAC 2021 Shared Task on Anaphora, Bridging, and Discourse Deixis in Dialogue","url":"https://aclanthology.org/2021.codi-sharedtask.1/","doi":"10.18653/v1/2021.codi-sharedtask.1","authors":["Sopan Khosla","Juntao Yu","Ramesh Manuvinakurike","Vincent Ng","Massimo Poesio","Michael Strube","Carolyn Rosé"],"year":2021,"venue":"CODI-CRAC 2021","abstract":"Defines shared tasks for anaphora, bridging, and discourse-deixis resolution over multiple conversational datasets, including end-to-end identification of discourse-deictic links rather than assuming ordinary entity antecedents."}
{"title":"Neural Anaphora Resolution in Dialogue","url":"https://aclanthology.org/2021.codi-sharedtask.2/","authors":["Hideo Kobayashi","Shengjie Li","Vincent Ng"],"year":2021,"venue":"CODI-CRAC 2021","abstract":"Describes neural systems for the CODI-CRAC dialogue shared task, including a discourse-deixis component that identifies and resolves anaphoric references to prior discourse material."}
{"title":"The CODI-CRAC 2021 Shared Task on Anaphora, Bridging, and Discourse Deixis Resolution in Dialogue: A Cross-Team Analysis","url":"https://aclanthology.org/2021.codi-sharedtask.8/","authors":["Shengjie Li","Hideo Kobayashi","Vincent Ng"],"year":2021,"venue":"CODI-CRAC 2021","abstract":"Analyzes systems submitted to the dialogue anaphora shared task across identity, bridging, and discourse-deixis resolution, comparing modeling choices and error patterns relevant to selecting discourse antecedents."}
{"title":"The CODI-CRAC 2022 Shared Task on Anaphora, Bridging, and Discourse Deixis in Dialogue","url":"https://aclanthology.org/2022.codi-crac.1/","authors":["Juntao Yu","Sopan Khosla","Ramesh Manuvinakurike","Lori Levin","Vincent Ng","Massimo Poesio","Michael Strube","Carolyn Rosé"],"year":2022,"venue":"CODI-CRAC 2022","abstract":"Extends the dialogue reference-resolution shared task with new test data and subtasks for directly detecting anaphoric relations, including discourse-deictic links in conversational data."}
{"title":"Anaphora Resolution in Dialogue: System Description (CODI-CRAC 2022 Shared Task)","url":"https://aclanthology.org/2022.codi-crac.2/","authors":["Tatiana Anikina","Natalia Skachkova","Joseph Renner","Priyansh Trivedi"],"year":2022,"venue":"CODI-CRAC 2022","abstract":"Describes a dialogue anaphora system whose discourse-deixis component combines antecedent resolution with prediction of the anaphoric expression's type, alongside related bridging and identity-resolution components."}
{"title":"Neural Anaphora Resolution in Dialogue Revisited","url":"https://aclanthology.org/2022.codi-crac.4/","authors":["Shengjie Li","Hideo Kobayashi","Vincent Ng"],"year":2022,"venue":"CODI 2022","abstract":"Revisits neural dialogue anaphora resolution using a span-based architecture and systematic hyperparameter optimization across identity, bridging, and discourse-deixis tracks."}
{"title":"End-to-End Neural Discourse Deixis Resolution in Dialogue","url":"https://aclanthology.org/2022.emnlp-main.778/","doi":"10.18653/v1/2022.emnlp-main.778","authors":["Shengjie Li","Vincent Ng"],"year":2022,"venue":"EMNLP 2022","abstract":"Presents an end-to-end neural model for discourse-deixis resolution in dialogue that identifies discourse-deictic anaphors and their antecedent spans rather than relying on gold anaphor or antecedent boundaries."}
{"title":"Discourse parsing for multi-party chat dialogues","url":"https://aclanthology.org/D15-1109/","doi":"10.18653/v1/D15-1109","authors":["Stergos Afantenos","Eric Kow","Nicholas Asher","Jérémy Perret"],"year":2015,"venue":"EMNLP 2015","abstract":"Addresses discourse parsing of multi-party chat by predicting which discourse units attach to which earlier units and which discourse relations hold between them, rather than assuming adjacent or gold argument pairs."}
{"title":"Discourse Structure and Dialogue Acts in Multiparty Dialogue: the STAC Corpus","url":"https://aclanthology.org/L16-1432/","authors":["Nicholas Asher","Julie Hunter","Mathieu Morey","Farah Benamara","Stergos Afantenos"],"year":2016,"venue":"LREC 2016","abstract":"Introduces the STAC corpus of multiparty chats annotated with elementary discourse units, discourse links, and relations under Segmented Discourse Representation Theory, including interleaved conversational threads and response relations."}
{"title":"Molweni: A Challenge Multiparty Dialogues-based Machine Reading Comprehension Dataset with Discourse Structure","url":"https://arxiv.org/abs/2004.05080","arxiv_id":"2004.05080","authors":["Jiaqi Li","Ming Liu","Min-Yen Kan","Zihao Zheng","Zekun Wang","Wenqiang Lei","Ting Liu","Bing Qin"],"year":2020,"venue":"COLING 2020","abstract":"Introduces a large multiparty-dialogue corpus with discourse-dependency annotations and question-answering data, including relations such as question-answer pairs, clarification, and correction as well as answerable and unanswerable questions."}
{"title":"Improving Dialogue Discourse Parsing via Reply-to Structures of Addressee Recognition","url":"https://aclanthology.org/2023.emnlp-main.526/","doi":"10.18653/v1/2023.emnlp-main.526","authors":["Yaxin Fan","Feng Jiang","Peifeng Li","Fang Kong","Qiaoming Zhu"],"year":2023,"venue":"EMNLP 2023","abstract":"Improves dialogue discourse parsing by jointly exploiting reply-to structure from addressee recognition, while predicting discourse attachments and relation labels on STAC and Molweni."}
{"title":"Dialogue Discourse Parsing as Generation: A Sequence-to-Sequence LLM-based Approach","url":"https://aclanthology.org/2024.sigdial-1.1/","doi":"10.18653/v1/2024.sigdial-1.1","authors":["Chuyuan Li","Yuwei Yin","Giuseppe Carenini"],"year":2024,"venue":"SIGDIAL 2024","abstract":"Formulates dialogue discourse parsing as sequence generation, producing discourse structures and relation labels for graph-structured conversational data such as STAC and Molweni."}
{"title":"Detection of Question-Answer Pairs in Email Conversations","url":"https://aclanthology.org/C04-1128/","authors":["Lokesh Shrestha","Kathleen McKeown"],"year":2004,"venue":"COLING 2004","abstract":"Identifies questions and their corresponding answers across email conversations by combining thread structure and textual evidence, directly addressing semantic response linkage in asynchronous workplace-style communication."}
{"title":"Agreement and Disputes in Dialogue","url":"https://www.research.ed.ac.uk/en/publications/agreement-and-disputes-in-dialogue/","doi":"10.3115/1622064.1622070","authors":["Alex Lascarides","Nicholas Asher"],"year":2008,"venue":"SIGDIAL 2008","abstract":"Develops a discourse-semantic account of agreement and dispute based on relational speech acts and shared public commitments, allowing responses to alter commitments associated with earlier discourse content."}
{"title":"Agreement, Disputes and Commitments in Dialogue","url":"https://academic.oup.com/jos/article-abstract/26/2/109/1695463","doi":"10.1093/jos/ffn013","authors":["Alex Lascarides","Nicholas Asher"],"year":2009,"published":"2009-02-06","venue":"Journal of Semantics","abstract":"Formalizes agreement and disagreement through public commitments and rhetorical relations, accounting for explicit and implicit agreement and for the particular discourse content over which interlocutors' commitments interact."}
{"title":"OK or not OK? Commitments in acknowledgments and corrections","url":"https://journals.linguisticsociety.org/proceedings/index.php/SALT/article/view/25.595","doi":"10.3765/salt.v25i0.3072","authors":["Antoine Venant","Nicholas Asher"],"year":2016,"published":"2016-04-07","venue":"Proceedings of SALT 25","abstract":"Develops a semantics of acknowledgments and corrections using structured public commitments, explaining how such responses accept, modify, or correct content contributed by preceding discourse."}
{"title":"Event-building through Role-filling and Anaphora Resolution","url":"https://aclanthology.org/P91-1003/","doi":"10.3115/981344.981347","authors":["Greg Whittemore","Melissa Macpherson","Greg Carlson"],"year":1991,"venue":"29th Annual Meeting of the Association for Computational Linguistics","abstract":"Explores event representations in discourse and the interaction between event construction and anaphora resolution, including cases in which event descriptions provide antecedents for subsequent reference."}
{"title":"A Twin-Candidate Based Approach for Event Pronoun Resolution using Composite Kernel","url":"https://aclanthology.org/C10-1022/","authors":["Bin Chen","Jian Su","Chew Lim Tan"],"year":2010,"venue":"COLING 2010","abstract":"Treats event-pronoun resolution as selection among candidate verbal event antecedents and learns pairwise preferences between competing antecedent candidates, including cases with no suitable antecedent."}
{"title":"Resolving Event Noun Phrases to Their Verbal Mentions","url":"https://aclanthology.org/D10-1085/","authors":["Bin Chen","Jian Su","Chew Lim Tan"],"year":2010,"venue":"EMNLP 2010","abstract":"Studies resolution of event-denoting noun phrases to earlier verbal mentions across potentially long discourse distances, using lexical, syntactic, morphological, semantic, and positional evidence for antecedent selection."}
{"title":"Joint Learning for Event Coreference Resolution","url":"https://aclanthology.org/P17-1009/","doi":"10.18653/v1/P17-1009","authors":["Jing Lu","Vincent Ng"],"year":2017,"venue":"ACL 2017","abstract":"Jointly models event coreference with event anaphoricity determination, providing transferable methods for deciding whether an event mention has a supported antecedent before antecedent selection."}
{"title":"Constrained Multi-Task Learning for Event Coreference Resolution","url":"https://aclanthology.org/2021.naacl-main.356/","doi":"10.18653/v1/2021.naacl-main.356","authors":["Jing Lu","Vincent Ng"],"year":2021,"venue":"NAACL 2021","abstract":"Uses constrained multi-task learning for event coreference together with related subtasks including event anaphoricity determination, providing transferable machinery for no-link decisions and antecedent-oriented event resolution."}
{"title":"The More Antecedents, the Merrier: Resolving Multi-Antecedent Anaphors","url":"https://aclanthology.org/P16-1216/","doi":"10.18653/v1/P16-1216","authors":["Hardik Vala","Andrew Piper","Derek Ruths"],"year":2016,"venue":"ACL 2016","abstract":"Addresses anaphoric expressions whose interpretation depends on multiple antecedents and develops a model that can recover sets of antecedent mentions rather than forcing every anaphor to select a single antecedent."}
{"title":"Free the Plural: Unrestricted Split-Antecedent Anaphora Resolution","url":"https://aclanthology.org/2020.coling-main.538/","doi":"10.18653/v1/2020.coling-main.538","authors":["Juntao Yu","Nafise Sadat Moosavi","Silviu Paun","Massimo Poesio"],"year":2020,"venue":"COLING 2020","abstract":"Develops end-to-end split-antecedent resolution without relying on gold identification of plural anaphors, allowing one anaphoric expression to be linked to multiple separately introduced antecedents."}
{"title":"Stay Together: A System for Single and Split-antecedent Anaphora Resolution","url":"https://aclanthology.org/2021.naacl-main.329/","doi":"10.18653/v1/2021.naacl-main.329","authors":["Juntao Yu","Nafise Sadat Moosavi","Silviu Paun","Massimo Poesio"],"year":2021,"venue":"NAACL 2021","abstract":"Provides a unified end-to-end architecture for single- and split-antecedent anaphora using predicted mentions, demonstrating how reference resolution can represent both ordinary and multi-antecedent links."}
{"title":"Scoring Coreference Chains with Split-Antecedent Anaphors","url":"https://aclanthology.org/2023.dnd-14.3/","doi":"10.5210/dad.2023.201","authors":["Silviu Paun","Juntao Yu","Nafise Sadat Moosavi","Massimo Poesio"],"year":2023,"venue":"Dialogue and Discourse","abstract":"Generalizes coreference evaluation metrics to structures containing split antecedents; the resulting framework supports evaluation of multi-antecedent plural reference and has also been applied in shared-task settings involving discourse deixis."}
===END llm_candidates.jsonl===
